389	<body>
390	  <main>
391	    <button type="button" class="circle-container" id="decorative-circle" aria-label="Interactive circle - click to activate, double-click or tap twice to change color" aria-pressed="false" aria-describedby="hint-text">
392	      <svg viewBox="0 0 400 400" aria-hidden="true" role="presentation">
393	        <circle cx="200" cy="200" r="200"/>
394	      </svg>
395	    </button>
396	    <div class="mode-indicator" id="mode-indicator" aria-live="polite" aria-atomic="true"></div>
397	    <div class="hint" id="hint-text" role="status" aria-live="polite" aria-relevant="text">Click or tap to activate</div>
398	    <div class="controls" role="group" aria-label="Circle controls">
399	      <button type="button" class="control-btn" id="cycle-btn" aria-label="Cycle to next color">Cycle Color</button>
400	      <button type="button" class="control-btn" id="reset-btn" aria-label="Reset to default state">Reset</button>
401	    </div>
402	    <div class="keyboard-hint" aria-label="Keyboard shortcuts">Press <kbd>C</kbd> to cycle • <kbd>R</kbd> to reset</div>
403	  </main>
404	
405	  <script defer>
406	    const CONFIG = {
407	      storageKey: 'circle-state',
408	      tapDelay: 300,
409	      colorShiftDuration: 500,
410	      colorModes: [
411	        { class: 'default', name: 'Default White' },
412	        { class: 'color-mode-1', name: 'Pink' },
413	        { class: 'color-mode-2', name: 'Teal' },
414	        { class: 'color-mode-3', name: 'Mint' }
415	      ],
416	      isTouch: 'ontouchstart' in window || navigator.maxTouchPoints > 0,
417	      pulseInterval: 2500
418	    };
419	
420	    const el = {
421	      circle: document.getElementById('decorative-circle'),
422	      hint: document.getElementById('hint-text'),
423	      modeIndicator: document.getElementById('mode-indicator'),
424	      cycleBtn: document.getElementById('cycle-btn'),
425	      resetBtn: document.getElementById('reset-btn')
426	    };
427	
428	    let state = { active: false, colorMode: 0 };
429	    let tapCount = 0;
430	    let tapTimeout = null;
431	    let animatingColorShift = false;
432	    let clickTimeout = null;
433	
434	    const getColorModeClass = (mode) => CONFIG.colorModes[mode % CONFIG.colorModes.length].class;
435	    const getColorModeName = (mode) => CONFIG.colorModes[mode % CONFIG.colorModes.length].name;
436	
437	    const storage = {
438	      save() {
439	        try {
440	          localStorage.setItem(CONFIG.storageKey, JSON.stringify(state));
441	        } catch {
442	          // Silently fail if localStorage is unavailable or quota exceeded
443	        }
444	      },
445	      load() {
446	        try {
447	          const saved = localStorage.getItem(CONFIG.storageKey);
448	          if (saved) {
449	            const parsed = JSON.parse(saved);
450	            if (parsed && typeof parsed === 'object') {
451	              state = { ...state, ...parsed };
452	            }
453	          }
454	        } catch {
455	          // Silently fail if parsing fails
456	        }
457	      }
458	    };
459	
460	    const updateClasses = () => {
461	      const colorClasses = CONFIG.colorModes.map(m => m.class);
462	      el.circle.classList.remove('active', ...colorClasses);
463	      el.circle.setAttribute('aria-pressed', state.active);
464	      if (state.active) el.circle.classList.add('active');
465	      if (state.colorMode > 0) el.circle.classList.add(getColorModeClass(state.colorMode));
466	    };
467	
468	    const updateUI = () => {
469	      let hintText = '';
470	
471	      if (CONFIG.isTouch) {
472	        hintText = state.active ? 'Tap to cycle colors • Tap circle again to deactivate' : 'Tap to activate • Tap twice to cycle';
473	      } else {
474	        hintText = state.active ? 'Double-click to cycle • Click to deactivate' : 'Click to activate • Double-click to cycle color';
475	      }
476	
477	      el.hint.textContent = hintText;
478	
479	      const showMode = state.active && state.colorMode > 0;
480	      el.modeIndicator.classList.toggle('visible', showMode);
481	      if (showMode) {
482	        const modeName = getColorModeName(state.colorMode);
483	        el.modeIndicator.textContent = `◆ ${modeName.toUpperCase()} MODE`;
484	      }
485	    };
486	
487	    const applyState = () => {
488	      updateClasses();
489	      updateUI();
490	    };
491	
492	    const toggleActive = () => {
493	      state.active = !state.active;
494	      applyState();
495	      storage.save();
496	    };
497	
498	    const cycleColor = () => {
499	      if (animatingColorShift) return;
500	      animatingColorShift = true;
501	      state.colorMode = (state.colorMode + 1) % CONFIG.colorModes.length;
502	      state.active = true;
503	      el.circle.classList.add('color-shifting');
504	      setTimeout(() => {
505	        el.circle.classList.remove('color-shifting');
506	        animatingColorShift = false;
507	      }, CONFIG.colorShiftDuration);
508	      applyState();
509	      storage.save();
510	    };
511	
512	    const resetState = () => {
513	      state = { active: false, colorMode: 0 };
514	      applyState();
515	      storage.save();
516	    };
517	
518	    let clickCount = 0;
519	    const handleClick = (e) => {
520	      clickCount++;
521	      clearTimeout(clickTimeout);
522	
523	      if (clickCount === 1) {
524	        clickTimeout = setTimeout(() => {
525	          if (clickCount === 1) toggleActive();
526	          clickCount = 0;
527	        }, CONFIG.tapDelay);
528	      } else if (clickCount === 2) {
529	        e.preventDefault();
530	        cycleColor();
531	        clickCount = 0;
532	      }
533	    };
534	
535	    const handleTouchEnd = () => {
536	      tapCount++;
537	      clearTimeout(tapTimeout);
538	      if (tapCount === 1) {
539	        tapTimeout = setTimeout(() => {
540	          if (tapCount === 1) toggleActive();
541	          tapCount = 0;
542	        }, CONFIG.tapDelay);
543	      } else if (tapCount === 2) {
544	        cycleColor();
545	        tapCount = 0;
546	      }
547	    };
548	
549	    const keyHandlers = {
550	      ' ': toggleActive,
551	      'enter': toggleActive,
552	      'c': cycleColor,
553	      'r': resetState
554	    };
555	
556	    const handleKeyDown = (e) => {
557	      const handler = keyHandlers[e.key.toLowerCase()];
558	      if (handler) {
559	        e.preventDefault();
560	        handler();
561	      }
562	    };
563	
564	    const initListeners = () => {
565	      el.circle.addEventListener('click', handleClick);
566	      el.circle.addEventListener('touchend', handleTouchEnd);
567	      el.circle.addEventListener('blur', () => {
568	        tapCount = 0;
569	        clickCount = 0;
570	        clearTimeout(tapTimeout);
571	        clearTimeout(clickTimeout);
572	      });
573	      document.addEventListener('keydown', handleKeyDown);
574	      el.cycleBtn.addEventListener('click', cycleColor);
575	      el.resetBtn.addEventListener('click', resetState);
576	    };
577	
578	    const initApp = () => {
579	      storage.load();
580	      applyState();
581	      initListeners();
582	      el.circle.focus();
583	    };
584	
585	    if (document.readyState === 'loading') {
586	      document.addEventListener('DOMContentLoaded', initApp);
587	    } else {
588	      initApp();
589	    }
590	  </script>
591	</body>
592	</html>
